def whichFloor(input):
    floor = 0
    for char in input:
        if char == '(':
            floor += 1
        elif char == ')':
            floor -= 1
    return floor

print(whichFloor(input))

def firstBasementPosition(input):
    floor = 0
    for position, char in enumerate(input, start=1):
        if char == '(':
            floor += 1
        elif char == ')':
            floor -= 1
        if floor == -1:
            return position
    return None

print(firstBasementPosition(input))